CREATE OR REPLACE FUNCTION public.can_access_service_area(_user uuid,_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user) AND _area IS NOT NULL AND CASE WHEN public.has_role(_user,'admin') THEN EXISTS(SELECT 1 FROM public.admin_permissions a WHERE a.user_id=_user AND (a.is_super_admin OR _area=ANY(a.coverage_ids))) ELSE EXISTS(SELECT 1 FROM public.staff_profiles p WHERE p.user_id=_user AND p.active AND _area=ANY(p.coverage_ids)) END $$;
CREATE OR REPLACE FUNCTION public.can_manage_service_area(_user uuid,_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user) AND _area IS NOT NULL AND public.has_role(_user,'admin') AND EXISTS(SELECT 1 FROM public.admin_permissions a WHERE a.user_id=_user AND (a.is_super_admin OR _area=ANY(a.coverage_ids))) $$;
REVOKE ALL ON FUNCTION public.can_access_service_area(uuid,text),public.can_manage_service_area(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_service_area(uuid,text),public.can_manage_service_area(uuid,text) TO anon,authenticated,service_role;